    }
  },
  "signal_basis": {
    "component_id": "C005.signal_basis",
    "value": "Check independent agreement or disagreement about the same booking and handoff, assessing sources' access and dependence. Calendar availability does not establish physical readiness, and corroborated timing alone does not establish the cause of lateness.",
    "scope": "Evidence bearing on whether availability updates explain the reported late starts, without presuming an update error or its causal effect.",
